// Long messages (real-world user test): the checker reads 6,000 characters at a time, and a forwarded chain is often longer, with the
// scam at the end. Longer text is checked in overlapping parts and the signs are combined, instead of being cut silently.
const CHECK_PART=6000,CHECK_MAX=30000;$('message').maxLength=CHECK_MAX;
function analyseLong(text){
 if(text.length<=CHECK_PART)return SafetyEngine.analyse(text);
 const parts=[];for(let i=0;i<text.length;i+=CHECK_PART-500)if(text.slice(i,i+CHECK_PART).trim())parts.push(text.slice(i,i+CHECK_PART));
 const rs=parts.map(p=>SafetyEngine.analyse(p)),seen=new Set(),matches=[],cautions=new Set(),ins={returns:[],links:[],payees:[]};
 for(const r of rs){r.matches.forEach(m=>{if(!seen.has(m.id)){seen.add(m.id);matches.push(m)}});(r.cautionContexts||[]).forEach(c=>cautions.add(c));
  for(const k of Object.keys(ins))((r.insights||{})[k]||[]).forEach(x=>{const key=JSON.stringify(x);if(!ins[k].some(y=>JSON.stringify(y)===key))ins[k].push(x)})}
 const ids=matches.map(m=>m.id);
 const merged={...rs[0],matches,cautionContexts:[...cautions].filter(c=>!seen.has(c)),coverage:rs.some(r=>r.coverage!=='unsupported')?'partial':'unsupported',insights:ins,risk:SafetyEngine.riskOf?SafetyEngine.riskOf(ids):rs[0].risk,parts:rs.length};
 // The reliability label must describe the combined signs, not only the first part.
 merged.reliability=SafetyEngine.reliabilityOf?SafetyEngine.reliabilityOf(ids,merged.risk,merged.coverage!=='unsupported'):undefined;
 return merged;
}
assess=text=>analyseLong(text).matches.map(withContent);
// Real-world inputs (real-world user test): a short question typed by the user ("ye msg sahi hai kya?") is not a message, and Marathi
// in Devanagari script is not Hindi; neither should get a plain "No known signs".
const MARATHI=/(?:^|[\s,.!?।])(?:आहे|आहेत|आणि|मध्ये|आमचे|आमच्या|तुमचे|तुमच्या|तुम्ही|करा|व्हा|नाही|फक्त|कमवा|मिळवा|झाले|केले|होईल|पाहिजे)(?=[\s,.!?।]|$)/g;
const looksMarathi=s=>(String(s).match(MARATHI)||[]).length>=2;
const looksLikeQuestion=s=>{const x=String(s).trim();return x.length<=100&&/\b(?:sahi|sahee|safe|asli|nakli|fake|real|genuine|fraud|froud|scam|thik|theek)\b|सही|असली|नकली|फ्रॉड|फ़्रॉड|ठीक/i.test(x)&&/[?？]|\b(?:kya|kyaa|is this|is it|msg|message|sms|call|link|mail)\b|क्या|मैसेज|मेसेज|संदेश|कॉल|लिंक/i.test(x)};
$('message').addEventListener('input',()=>{if($('message').value.length>=CHECK_MAX)audioStatus.textContent=t('Only the first 30,000 characters are kept.','केवल पहले 30,000 अक्षर रखे गए हैं।')});
// Message check result (model v3): a traffic-light verdict first, then the reasons in order of weight, the plain-number
