// works with a v2 engine that has no risk or insights fields.
const VERDICT={high:['High risk: stop. Do not pay, share any code or install anything because of this message.','ज़्यादा खतरा: रुकें। इस संदेश के कहने पर भुगतान न करें, कोई कोड न बताएँ, कुछ इंस्टॉल न करें।'],caution:['Caution: check independently before you act on this message.','सावधानी: इस संदेश के कहने पर कुछ भी करने से पहले खुद जाँच करें।'],none:['No known warning signs found. This does not mean it is safe.','खतरे का कोई जाना-पहचाना संकेत नहीं मिला। इसका मतलब यह नहीं कि संदेश सुरक्षित है।']};
const LINK_VERDICT={official:['official website','आधिकारिक वेबसाइट'],shortener:['shortened link: it hides where it goes','छोटा किया गया लिंक: असली पता छिपाता है'],apk:['app file (APK): do not install it','ऐप फ़ाइल (APK): इसे इंस्टॉल न करें'],ip:['a bare number address, not a normal official website','केवल अंकों वाला पता, सामान्य आधिकारिक वेबसाइट नहीं'],lookalike:['imitates an official website','आधिकारिक वेबसाइट की नकल'],unofficial:['not an official website','आधिकारिक वेबसाइट नहीं']};
// SEBI's F&O study is shown for F&O wording, or for trading tips and borrowing to trade; not for every tips or IPO message (D31).
const FNO_TERMS=/\bf\s?&\s?o\b|\bfutures\b|\boptions?\s+(?:trading|trades?|calls?|puts?|buying|selling|tips?)\b|\b(?:call|put)\s+options?\b|\boption\s+chain\b|\b(?:bank\s?nifty|fin\s?nifty|nifty)\b|\bintraday\b|एफ\s?एंड\s?ओ|फ़?्यूचर्स|(?:ऑप्शंस?|ऑप्शन)\s*(?:ट्रेडिंग|टिप्स?|कॉल)|(?:कॉल|पुट)\s*ऑप्शन|निफ़?्टी|इंट्राडे/i;
const riskOf=result=>result.risk&&result.risk.level?result.risk:{level:result.matches.length>=2?'high':result.matches.length?'caution':'none',score:null,reasons:result.matches.map(m=>m.id)};
