 const fallback=()=>{let area=$('shareText');if(!area){area=el('textarea');area.id='shareText';area.readOnly=true;area.rows=5;area.setAttribute('aria-label',t('Warning to copy','कॉपी करने के लिए चेतावनी'));$('result').append(area)}area.value=text;area.focus();area.select();audioStatus.textContent=t('Copy this warning and send it to your family.','यह चेतावनी कॉपी करके परिवार को भेजें।')};
