// Design refresh (owner, 3 Oct 2026: simpler, classy, green-and-white, animated line pictures). Green line drawings from
// NS_ART (app-owned static SVG, never user text) are placed on Home, on each page header and above the check and
// "Before you pay" answers. The footer's long notes fold under one line. Nothing here changes what any tool does.
{
const ART=typeof NS_ART!=='undefined'?NS_ART:{};
// Parsed as SVG documents and imported node by node, so the app still uses no innerHTML anywhere (security review).
const SVGP=new DOMParser();
const artEl=(name,cls)=>{const s=el('span',undefined,'art'+(cls?' '+cls:''));s.setAttribute('aria-hidden','true');const src=ART[name];if(src){const doc=SVGP.parseFromString(/xmlns=/.test(src)?src:src.replace('<svg','<svg xmlns="http://www.w3.org/2000/svg"'),'image/svg+xml'),svg=doc.documentElement;if(svg&&svg.nodeName==='svg'&&!doc.querySelector('parsererror'))s.append(document.importNode(svg,true))}return s};
// Home: a calm drawing beside the one question, and a drawing on every task tile in place of the small icon.
const homeT=$('homeTitle');if(homeT&&ART.hero)homeT.before(artEl('hero','art-hero home-art'));
const TILE={check:'check',paycheck:'pay',emergency:'urgent',route:'complain',rights:'rights',practice:'practice',family:'family'};
document.querySelectorAll('#home .task-card[data-go]').forEach(b=>{const n=TILE[b.dataset.go];if(n&&ART[n])b.prepend(artEl(n,'tile-art'))});
// Each page opens with a small drawing beside its heading. Pages that rebuild themselves (Rights and help on a language
// switch) get it back after every rebuild and on every visit.
const PAGE={check:'check',paycheck:'pay',emergency:'urgent',route:'complain',rights:'rights',draft:'packet',profile:'plan',practice:'practice',family:'family'};
const pageArt=id=>{const sec=$(id),n=PAGE[id];if(sec&&n&&ART[n]&&!sec.querySelector(':scope>.page-art'))sec.prepend(artEl(n,'page-art'))};
// Only the page on screen gets its drawing now; the others get theirs on first visit (less work while a slow phone loads).
pageArt(active);
// Rights and help: each institution's rights fold under one row (its name and how many rights), like the guides above.
const foldRights=()=>document.querySelectorAll('#rights .rights-group').forEach(g=>{if(g.querySelector(':scope>details'))return;const h=g.querySelector(':scope>h3'),cards=[...g.querySelectorAll(':scope>.right-card')];if(!h||!cards.length)return;const d=el('details',undefined,'rights-fold'),s=el('summary');s.append(h,el('span',t(cards.length===1?'1 right':cards.length+' rights',cards.length+' अधिकार'),'fold-count'));d.append(s,...cards);g.append(d)});
if(typeof renderRights==='function'){const rr=renderRights;renderRights=function(){rr.apply(this,arguments);foldRights();if(active==='rights')pageArt('rights')};foldRights()}
{const goArt=go;go=function(tab){goArt(tab);pageArt(tab)}}
{const trArt=translate;translate=function(){trArt();pageArt(active)}}
// Answers lead with a drawing of their level; the drawing never says "safe" (no tick on "no known signs").
const levelArt=v=>{const l=v.dataset.level||v.dataset.verdict||'';return l==='high'||l==='stop'?'high':l==='caution'||l==='verify'?'caution':'nosigns'};
const decorate=(boxId,verdictId)=>{const box=$(boxId);if(!box)return;const put=()=>{const v=$(verdictId);if(!v||box.querySelector(':scope>.verdict-art'))return;const want=levelArt(v);if(ART[want])box.prepend(artEl(want,'verdict-art'))};new MutationObserver(put).observe(box,{childList:true});put()};
decorate('result','riskVerdict');decorate('payResult','payVerdict');
// The voice and photo tips fold under one line beside the Paste button.
{const ih=document.querySelector('#check .input-help'),tips=ih?[...ih.querySelectorAll(':scope>p')]:[];if(tips.length&&!ih.querySelector('details.input-tips')){const d=el('details',undefined,'input-tips');d.append(bilingual('summary','Speak it, or copy it from a photo','बोलकर या फ़ोटो से कॉपी करके डालें'),...tips);ih.append(d)}}
// Home's language line becomes one short question; the helplines page it opens lists every language.
{const p=document.querySelector('#otherLanguage p');if(p){p.dataset.en='Speak another language?';p.dataset.hi='कोई और भाषा बोलते हैं?';p.textContent=t(p.dataset.en,p.dataset.hi)}}
// Footer: one quiet line; the full notes (disclaimer, sources checked, privacy) open on request.
const foot=document.querySelector('footer');
if(foot&&!foot.querySelector('details.about-app')){const d=el('details',undefined,'about-app'),inner=el('div');while(foot.firstChild)inner.append(foot.firstChild);d.append(bilingual('summary','About this app, privacy and sources','इस ऐप के बारे में, निजता और स्रोत'),inner);foot.append(bilingual('p','Free · no ads · no tips · nothing you type is saved or sent','मुफ़्त · कोई विज्ञापन नहीं · कोई टिप नहीं · आपका लिखा न सेव होता है, न भेजा जाता है','footer-line'),d)}
}
// Market comparison (3 Oct 2026), idea G10: scams work by rushing people, and some phones now add a short pause during risky
// calls. Where the app says stop (Before you pay: STOP; a High-risk message), it offers "Pause for 30 seconds": a calm screen
// with a ring that empties over 30 seconds. A general safety step, not a rule from any one official page. Nothing is saved.
{
const pd=el('dialog',undefined,'pause-dialog');pd.id='pauseDialog';pd.setAttribute('aria-labelledby','pauseTitle');document.body.append(pd);
let pauseTimer=null;
const pauseRing=()=>{const ns='http://www.w3.org/2000/svg',s=document.createElementNS(ns,'svg');s.setAttribute('viewBox','0 0 120 120');s.setAttribute('class','pause-ring');s.setAttribute('aria-hidden','true');s.setAttribute('focusable','false');
 for(const cls of ['pause-track','pause-progress']){const c=document.createElementNS(ns,'circle');c.setAttribute('cx','60');c.setAttribute('cy','60');c.setAttribute('r','52');c.setAttribute('pathLength','1');c.setAttribute('class',cls);s.append(c)}return s};
function openPause(){
 clearInterval(pauseTimer);pd.replaceChildren();
 const h=el('h2',t('Pause for 30 seconds','30 सेकंड रुकें'));h.id='pauseTitle';
 const wrap=el('div',undefined,'pause-ring-wrap'),num=el('span','30','pause-count');wrap.append(pauseRing(),num);
 const body=el('p',t('Close the chat or hang up, and take a slow breath. Scammers rush you so that you cannot think; a real company or official can wait. Then call someone you trust, or check with the official app or website yourself.','चैट बंद करें या कॉल काट दें, और धीरे से साँस लें। धोखेबाज़ जल्दी इसलिए मचाते हैं ताकि आप सोच न सकें; असली कंपनी या अधिकारी इंतज़ार कर सकते हैं। फिर किसी भरोसेमंद व्यक्ति को फ़ोन करें, या आधिकारिक ऐप या वेबसाइट पर खुद जाँचें।'),'pause-body');
 const tag=el('p',t('General safety step','सामान्य सुरक्षा कदम'),'small pause-tag'),status=el('p','','pause-status');status.setAttribute('role','status');
 const close=el('button',t('Close','बंद करें'),'primary');close.type='button';close.id='pauseClose';close.onclick=()=>pd.close();
 pd.append(h,wrap,body,tag,status,close);
 let left=30;try{pd.showModal()}catch(e){pd.setAttribute('open','')}close.focus();
 pauseTimer=setInterval(()=>{left--;num.textContent=String(Math.max(left,0));if(left<=0){clearInterval(pauseTimer);wrap.classList.add('done');status.textContent=t('Thirty seconds. Now decide calmly.','30 सेकंड हो गए। अब शांति से फ़ैसला करें।')}},1000)}
pd.addEventListener('close',()=>clearInterval(pauseTimer));
const pauseButton=id=>{const b=el('button',t('Pause for 30 seconds','30 सेकंड रुकें'),'pause-button');b.type='button';b.id=id;b.onclick=openPause;return b};
// Offered after STOP in Before you pay (right under the verdict) and in a High-risk result's action buttons.
const offerPause=(boxId,verdictId,want,id,where)=>{const box=$(boxId);if(!box)return;const put=()=>{const v=$(verdictId);if(!v||document.getElementById(id))return;if((v.dataset.verdict||v.dataset.level)!==want)return;const b=pauseButton(id);if(where==='actions'){const a=$('resultActions');if(a)a.append(b)}else v.after(b)};new MutationObserver(put).observe(box,{childList:true});put()};
offerPause('payResult','payVerdict','stop','payPause','after');
offerPause('result','riskVerdict','high','checkPause','actions');
}
// Dark theme (owner, 3 Oct 2026: "make the light theme default ... the dark theme option will be in side bar so i have to select
// the dark theme if i want"). The app always opens in the light theme, whatever the device's own setting; "Dark theme" in the
// menu, beside "Larger text", switches it for this visit. Nothing is saved (the app keeps no storage), so the next visit opens
// in the light theme again. Colours are in theme.css.
{
const root=document.documentElement;
ICON_PATHS.moon='M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z';
const themeBtn=bilingual('button','Dark theme','डार्क थीम');themeBtn.id='themeToggle';themeBtn.type='button';withIcon(themeBtn,'moon');
// The browser's own bar matches the top bar.
const barColor=document.createElement('meta');barColor.name='theme-color';document.head.append(barColor);
// Colours change at once, without the buttons' short fade.
const quiet=()=>{root.classList.add('ns-theme-switch');requestAnimationFrame(()=>requestAnimationFrame(()=>root.classList.remove('ns-theme-switch')))};
const applyTheme=dark=>{quiet();root.dataset.theme=dark?'dark':'light';themeBtn.setAttribute('aria-pressed',String(dark));barColor.content=dark?'#072219':'#ffffff'};
themeBtn.onclick=()=>applyTheme(root.dataset.theme!=='dark');
big.after(themeBtn);applyTheme(false);
}
